import java.util.*;

class Solution {
    public boolean canServe(int[][] rides, int seats) {
        int maxKm = 0;
        for (int[] r : rides) maxKm = Math.max(maxKm, r[2]);
        int[] change = new int[maxKm + 1];
        for (int[] r : rides) {
            change[r[1]] += r[0];   // board
            change[r[2]] -= r[0];   // leave (same index -> seats freed first)
        }
        int load = 0;
        for (int km = 0; km <= maxKm; km++) {
            load += change[km];
            if (load > seats) return false;
        }
        return true;
    }
}

